use std::env;
use axum::{Router, body::{Body, to_bytes}, extract::Request, http::{HeaderMap, StatusCode, header}, response::{IntoResponse, Response}, routing::{any, get, post}};
use fullstack_agent_046::{RequestInput, calculate};
use serde::Serialize;
use serde_json::json;
use tower_http::services::{ServeDir, ServeFile};

const MAX_BODY_BYTES: usize = 16_384;
const BROWSER_MODULE: &str = r#"const asI64=(v,n)=>{if(typeof v==='bigint')return v;if(!Number.isSafeInteger(v))throw new TypeError(`${n} must be a safe whole number`);return BigInt(v)};export async function loadParley(){const r=await fetch(new URL('/fullstack_agent_046.wasm',import.meta.url));const m=(await WebAssembly.instantiateStreaming(r)).instance.exports;return {archive_transfer_rating:(a0,a1,a2,a3)=>m.parley_browser_score(asI64(a0,'a0'),asI64(a1,'a1'),asI64(a2,'a2'),a3?1:0)}}"#;

fn json_response(value: impl Serialize, status: u16, headers: &[(&str, &str)]) -> Response {
    if headers.iter().any(|(n, _)| matches!(n.to_ascii_lowercase().as_str(), "content-length" | "content-type" | "connection" | "transfer-encoding" | "x-content-type-options")) {
        return error("invalid_response_headers", 500, "server-owned response header");
    }
    let mut response = (StatusCode::from_u16(status).unwrap(), serde_json::to_vec(&value).unwrap()).into_response();
    response.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("application/json"));
    for (n, v) in headers {
        response.headers_mut().insert(header::HeaderName::from_bytes(n.as_bytes()).unwrap(), header::HeaderValue::from_str(v).unwrap());
    }
    response
}

fn error(code: &str, status: u16, detail: &str) -> Response {
    let mut r = (StatusCode::from_u16(status).unwrap(), serde_json::to_vec(&json!({"error": code, "detail": detail})).unwrap()).into_response();
    r.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("application/json"));
    r
}

fn zero(v: &RequestInput, state: &str) -> serde_json::Value {
    json!({"transfer_tag":v.transfer_tag,"volume_tally":0,"relocation_effort":0,"cart_allowance":0,"shelved_effort":0,"quarantined_effort":0,"transfer_rounds":0,"transfer_rating":0,"transfer_phase":state})
}

fn decide(v: RequestInput, _headers: &HeaderMap) -> Response {
    if [v.folio_boxes, v.atlas_tubes, v.catalog_carts].iter().any(|x| *x < 0) {
        return json_response(zero(&v, "invalid"), 422, &[("x-validation", "nonnegative")]);
    }
    if v.catalog_carts == 0 && v.folio_boxes + v.atlas_tubes > 0 {
        return json_response(zero(&v, "invalid"), 422, &[("x-validation", "catalog_carts")]);
    }
    let body = calculate(&v);
    let owned = vec![("location", format!("/api/v10/archive-transfers/{}", v.transfer_tag)), ("x-transfer-phase", body.transfer_phase.clone())];
    let refs: Vec<(&str, &str)> = owned.iter().map(|(a, b)| (*a, b.as_str())).collect();
    json_response(body, 201, &refs)
}

async fn status() -> Response { json_response(json!({"service":"Archive Transfer","ready":true}), 200, &[]) }

async fn endpoint(request: Request) -> Response {
    let headers = request.headers().clone();
    let media = headers.get(header::CONTENT_TYPE).and_then(|v| v.to_str().ok()).unwrap_or("").split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    if media != "application/json" && !media.ends_with("+json") { return error("json_content_type_required", 415, "expected application/json"); }
    if let Some(length) = headers.get(header::CONTENT_LENGTH) {
        let declared = length.to_str().ok().and_then(|v| v.parse::<usize>().ok());
        if declared.is_none_or(|v| v > MAX_BODY_BYTES) { return error("body_too_large", 413, "request body exceeds 16384 bytes"); }
    }
    let body = match to_bytes(request.into_body(), MAX_BODY_BYTES).await { Ok(body) => body, Err(_) => return error("body_too_large", 413, "request body exceeds 16384 bytes") };
    match serde_json::from_slice::<RequestInput>(&body) { Ok(v) => decide(v, &headers), Err(reason) => error("invalid_json", 400, &reason.to_string()) }
}

async fn missing(request: Request<Body>) -> Response { error("not_found", 404, &format!("no API route {}", request.uri().path())) }
async fn browser() -> Response { let mut r = BROWSER_MODULE.into_response(); r.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("text/javascript; charset=utf-8")); r }

#[tokio::main]
async fn main() {
    let wasm = env::var_os("FULLSTACK_046_WASM").map(std::path::PathBuf::from).unwrap();
    let app = Router::new().route("/status/archive-transfer-ready", get(status)).route("/api/v10/archive-transfers", post(endpoint)).route("/api/{*rest}", any(missing)).route("/parley.js", get(browser)).route_service("/fullstack_agent_046.wasm", ServeFile::new(wasm)).fallback_service(ServeDir::new("public").append_index_html_on_directories(true));
    let port = env::var("PARLEY_WEB_PORT").unwrap().parse::<u16>().unwrap();
    let listener = tokio::net::TcpListener::bind(("127.0.0.1", port)).await.unwrap();
    axum::serve(listener, app).await.unwrap()
}
